def finde_gewinner(wuerfe):
    beste = 0
    for i in range(len(wuerfe)):
        if wuerfe[i] > wuerfe[beste]:
            beste = i
    return beste

gewinner = finde_gewinner([4, 6, 2])
print(f"Gewinner: Spieler {gewinner + 1}")

